const session = require('./armorSession')
const ArmorKeyring = require('./armorKeyring')
const ArmorApprovalRequest = require('./armorApprovalRequest')
let runSync

function sync (operation, options, args) {
  if (!runSync) {
    const { createSyncFn } = require('@dotenvx/tooling')
    runSync = createSyncFn(require.resolve('./armorWorker.js'), { timeout: 330000 })
  }
  // UI callbacks stay in the async caller; functions cannot cross the worker boundary.
  const { hostname, token, devicePublicKey, cliVersion, armor, noArmor, processEnv } = options
  const result = runSync(operation, { hostname, token, devicePublicKey, cliVersion, armor, noArmor, processEnv }, args)
  if (result.error) throw Object.assign(new Error(result.error.message), result.error)
  return result.value
}

module.exports = function armor (options = {}) {
  return {
    async get (publicKey) {
      const resolved = await session(options)
      if (!resolved) return {}
      return new ArmorKeyring(resolved, publicKey).run()
    },
    getSync (publicKey) {
      const resolved = session.sync(options)
      if (!resolved) return {}
      return sync('get', resolved, [publicKey])
    },
    async decrypt (src, context = {}) {
      const resolved = await session(options)
      if (!resolved) throw Object.assign(new Error('[ARMOR_NOT_CONFIGURED] sign in to Armor'), { code: 'ARMOR_NOT_CONFIGURED' })
      return new ArmorApprovalRequest(resolved, 'decrypt', {
        public_key: context.publicKey,
        src,
        ...(context.grantToken ? { grant_token: context.grantToken } : {})
      }).run()
    },
    decryptSync (src, context = {}) {
      const resolved = session.sync(options)
      if (!resolved) throw Object.assign(new Error('[ARMOR_NOT_CONFIGURED] sign in to Armor'), { code: 'ARMOR_NOT_CONFIGURED' })
      return sync('decrypt', resolved, [src, { publicKey: context.publicKey, grantToken: context.grantToken }])
    }
  }
}
